mapper.select:
SELECT KSKK_MST.APKIHONCD APKIHONCD, KSKK_MST.SHOPCD SHOPCD, KSKK_MST.SHIMEDDN1 SHIMEDDN1, KSKK_MST.FURIKAEDDN1 FURIKAEDDN1, KSKK_MST.KSIKKNCD KSIKKNCD, KSKK_MST.KSIKKNNM KSIKKNNM, KSIKKNKIND_NM.MOJISETTEIATAI KSIKKNKIND, ACIKEIYUKSIKBN_NM.ITEMNM ACIKEIYUKSIKBN, KSKK_MST.YUKOKBN YUKOKBN, YUKOKBN_NM.ITEMNM YUKOKBNNM FROM S02M025T KSKK_MST LEFT OUTER JOIN S02M006T KSIKKNKIND_NM ON KSIKKNKIND_NM.APKIHONCD = '000' AND KSIKKNKIND_NM.SHOPCD = '000' AND KSIKKNKIND_NM.SETTEINO = '004' AND KSIKKNKIND_NM.RCRDKBN = 'M' AND KSIKKNKIND_NM.SETTEICD = KSKK_MST.KSIKKNKIND LEFT OUTER JOIN S01M004T ACIKEIYUKSIKBN_NM ON ACIKEIYUKSIKBN_NM.CONDITIONID = 'CN012' AND ACIKEIYUKSIKBN_NM.SETTEIATAI = KSKK_MST.ACIKEIYUKSIKBN LEFT OUTER JOIN S01M004T YUKOKBN_NM ON YUKOKBN_NM.CONDITIONID = 'CN001' AND YUKOKBN_NM.SETTEIATAI = KSKK_MST.YUKOKBN WHERE KSKK_MST.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND KSKK_MST.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND KSKK_MST.KSIKKNCD LIKE #{ksikkncd,jdbcType=VARCHAR} || '%'
AND KSKK_MST.KSIKKNNM LIKE '%' || #{ksikknnm,jdbcType=VARCHAR} || '%'
AND KSKK_MST.KSIKKNKIND = #{ksikknkind,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
AND KSKK_MST.YUKOKBN = #{yukokbn,jdbcType=VARCHAR}
AND ROWNUM <= #{rownum,jdbcType=VARCHAR} + 1 ORDER BY KSKK_MST.APKIHONCD, KSKK_MST.SHOPCD, KSKK_MST.KSIKKNCD

SELECT APKIHONCD ,SHOPCD ,SHIMEDYDM ,GMOSPID ,SKYSAKICD ,GMOCRDCMPNYNO ,GMOKAIINNO ,GMOYUKOKGN ,GMOJIYUKOMOKUN1 ,GMOJIYUKOMOKUN2 ,ACIKEIYUKSIKBN FROM S09W005T
WHERE SHIMEDYDM = #{shimedydm,jdbcType=VARCHAR}
AND APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
AND SHOPCD = #{shopcd,jdbcType=VARCHAR} AND NOT IRAIDD IS NULL ORDER BY GMOSPID ,GMOKAIINNO ,SKYSAKICD
